package com.vanigam.clothing;
import android.app.Activity;
import android.webkit.*;
import android.print.*;
import org.json.*;
import java.util.Locale;
public final class BillPrint {
 static String e(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 static String cash(long p){return String.format(Locale.US,"₹ %,.2f",p/100.0);}
 public static String html(JSONObject b)throws Exception{JSONObject shop=b.getJSONObject("shop");String logo=shop.optString("logo");if(!logo.matches("[A-Za-z0-9+/=]*"))logo="";
  StringBuilder s=new StringBuilder("<!doctype html><html><head><meta charset='UTF-8'><style>@page{size:A5 portrait;margin:8mm}body{font:11px sans-serif;color:#10233f;margin:0}h1{font-size:20px;margin:3px 0}p{margin:3px 0;white-space:pre-wrap;overflow-wrap:anywhere}.head{text-align:center;border-bottom:2px solid #10233f;padding-bottom:9px}.logo{max-height:18mm;max-width:35mm}.meta{display:flex;justify-content:space-between;gap:12px;padding:10px 0;font-size:10px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th{text-align:left;border-block:1px solid #789;padding:7px 4px;background:#edf1f8}td{padding:7px 4px;border-bottom:1px solid #dde2e9;overflow-wrap:anywhere;vertical-align:top}tr{break-inside:avoid}th:nth-child(n+2),td:nth-child(n+2){text-align:right}small{color:#56667c;font-size:9px}.total{break-inside:avoid;padding-top:12px}.sum{display:flex;justify-content:space-between;margin:5px 0}.grand{font-size:18px;font-weight:bold;border-block:2px solid #10233f;padding:9px 0}.foot{text-align:center;margin-top:16px;font-size:10px}</style></head><body><div class='head'>");
  if(!logo.isEmpty())s.append("<img class='logo' src='data:image/png;base64,").append(logo).append("'>");s.append("<h1>").append(e(shop.getString("name"))).append("</h1><p>").append(e(shop.optString("address"))).append("</p><p>").append(e(shop.optString("phone"))).append("</p>");if(!shop.optString("gstin").isEmpty())s.append("<p>GSTIN: ").append(e(shop.getString("gstin"))).append("</p>");s.append("</div><div class='meta'><div><b>RETAIL BILL · C-").append(b.getLong("number")).append("</b><p>").append(e(b.getString("time"))).append("</p><p>Cashier: ").append(e(b.getString("cashier"))).append("</p></div><div>").append(e(b.getString("customerName"))).append("<p>").append(e(b.getString("mobile"))).append("</p></div></div><table><colgroup><col style='width:49%'><col style='width:10%'><col style='width:19%'><col style='width:22%'></colgroup><thead><tr><th>Product</th><th>Qty</th><th>Rate</th><th>Amount</th></tr></thead><tbody>");
  JSONArray lines=b.getJSONArray("lines");for(int i=0;i<lines.length();i++){JSONObject l=lines.getJSONObject(i);s.append("<tr><td><b>").append(e(l.getString("name"))).append("</b><br><small>").append(e(l.getString("sku")+" · "+l.getString("size")+" · "+l.getString("colour"))).append("</small></td><td>").append(l.getLong("qty")).append("</td><td>").append(cash(l.getLong("price"))).append("</td><td>").append(cash(l.getLong("amount"))).append("</td></tr>");}s.append("</tbody></table><div class='total'>");sum(s,"Subtotal",cash(b.getLong("subtotal")));if(b.getLong("discount")>0)sum(s,"Discount","− "+cash(b.getLong("discount")));if(b.getLong("reward")>0)sum(s,"Points discount ("+b.getLong("redeem")+" pts)","− "+cash(b.getLong("reward")));s.append("<div class='sum grand'><span>TOTAL</span><span>").append(cash(b.getLong("total"))).append("</span></div>");if(b.getLong("tax")>0)sum(s,"Included tax ("+shop.getDouble("taxRate")+"%)",cash(b.getLong("tax")));for(String method:new String[]{"cash","upi","card"})if(b.getLong(method)>0)sum(s,method.toUpperCase(Locale.US),cash(b.getLong(method)));if(b.getLong("cash")>0){sum(s,"Cash received",cash(b.getLong("received")));sum(s,"Balance returned",cash(b.getLong("change")));}if(!b.getString("mobile").isEmpty())sum(s,"Points earned / used",b.getLong("earned")+" / "+b.getLong("redeem"));s.append("</div><p class='foot'>").append(e(shop.optString("footer"))).append("</p></body></html>");return s.toString();
 }
 static void sum(StringBuilder s,String title,String value){s.append("<div class='sum'><span>").append(e(title)).append("</span><span>").append(e(value)).append("</span></div>");}
 public static WebView print(Activity a,JSONObject b)throws Exception{WebView view=new WebView(a);view.getSettings().setJavaScriptEnabled(false);view.getSettings().setAllowFileAccess(false);view.setWebViewClient(new WebViewClient(){boolean printed;public void onPageFinished(WebView v,String url){if(printed)return;printed=true;PrintManager manager=(PrintManager)a.getSystemService(Activity.PRINT_SERVICE);manager.print("Vanigam-A5-C-"+b.optLong("number"),v.createPrintDocumentAdapter("Bill C-"+b.optLong("number")),new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A5).setColorMode(PrintAttributes.COLOR_MODE_COLOR).setMinMargins(new PrintAttributes.Margins(315,315,315,315)).build());}});view.loadDataWithBaseURL("https://receipt.invalid/",html(b),"text/html","UTF-8",null);return view;}
}
